"""Execution registry and the tool schema advertised to the model."""
import copy
import json


SYSTEM_PROMPT = """You are an agent interacting with a text-based household environment.
Complete the user's task using the provided tools.

Call exactly one tool at each turn.
Use object and location identifiers as they appear in observations.
Explore the environment to obtain missing information.
The initial observation lists places you can visit. Move to a place to inspect its contents.
Objects in closed containers are hidden until the container is opened at its location.
Looking only describes the current location; it does not search other places in the room.
When an observation is unchanged, explore a different place or try a different action.
Use tool results to track the environment and decide your next action.
If a call fails, use the feedback to decide how to proceed.
Do not claim task completion; success is determined by the environment."""

# Native ALFWorld uses "move ... to ..." for placement, not "put ... in ...".
REGISTRY = {
    "look": ("Observe only your current location, not the whole room. At the room center it may show nothing; move to a listed location to explore.", (), "look"),
    "inventory": ("Inspect the objects you are holding.", (), "inventory"),
    "go_to": ("Move to a receptacle or location listed in observations and see its visible contents. Use this to explore, not the name of a small object.", ("destination",), "go to {destination}"),
    "open": ("Open a container at your current location to reveal its contents.", ("target",), "open {target}"),
    "close": ("Close a container at your current location.", ("target",), "close {target}"),
    "examine": ("Inspect an accessible object or receptacle at your current location. Does not move you there.", ("target",), "examine {target}"),
    "take": ("Take a visible object from the receptacle at your current location. A closed container must be opened first. You can hold only one object at a time.", ("object", "source"), "take {object} from {source}"),
    "put": ("Place your held object in or on a receptacle at your current location. Open a closed destination first.", ("object", "destination"), "move {object} to {destination}"),
    "use": ("Use an accessible object, such as switching on a lamp at your current location. To examine an object under a lamp, hold the object when using the lamp.", ("target",), "use {target}"),
    "clean": ("Clean your held object at a sinkbasin. Move to the sinkbasin first.", ("object", "receptacle"), "clean {object} with {receptacle}"),
    "heat": ("Heat your held object using a microwave at your current location.", ("object", "receptacle"), "heat {object} with {receptacle}"),
    "cool": ("Cool your held object using a fridge at your current location.", ("object", "receptacle"), "cool {object} with {receptacle}"),
}
# Maps executor names to the names advertised in the tool schema.
SCHEMA_NAMES = {name: name + "_object" for name in ("clean", "heat", "cool")}


def tool_schemas():
    schemas = []
    for name, (description, fields, _) in REGISTRY.items():
        schemas.append({"type": "function", "function": {
            "name": SCHEMA_NAMES.get(name, name),
            "description": description,
            "parameters": {"type": "object", "properties": {
                field: {"type": "string", "description": "Exact identifier from observations, including its number."}
                for field in fields
            }, "required": list(fields), "additionalProperties": False},
        }})
    return copy.deepcopy(schemas)


class ToolCallError(ValueError):
    pass


def command_for(name, arguments):
    if name not in REGISTRY:
        raise ToolCallError("unknown_tool")
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments)
        except (ValueError, TypeError):
            raise ToolCallError("invalid_arguments: expected a JSON object") from None
    fields = REGISTRY[name][1]
    if not isinstance(arguments, dict) or set(arguments) != set(fields):
        raise ToolCallError("invalid_arguments: required fields are " + ", ".join(fields))
    for value in arguments.values():
        if not isinstance(value, str) or not value.strip() or any(c in value for c in "\r\n\x00"):
            raise ToolCallError("invalid_arguments: identifiers must be nonempty single-line strings")
    return REGISTRY[name][2].format(**{key: value.strip() for key, value in arguments.items()})

"""Per-rollout state, shared by training, validation and integration tests."""
import json

from alfworld_case.tools import SYSTEM_PROMPT, ToolCallError, command_for


class Episode:
    def __init__(self, env, max_steps=40):
        if max_steps < 1:
            raise ValueError("max_steps must be positive")
        self.env = env
        self.max_steps = max_steps

    def reset(self, game_relative_path, task_id=None):
        self.observation, self.info = self.env.reset_with_info(game_relative_path, task_id)
        self.initial_observation = self.observation
        self.history = []
        self.num_steps = 0
        self.done = False
        self.success = False
        self.env_reward_sum = 0.0
        return self.observation

    def messages(self):
        messages = [{"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": self.initial_observation}]
        for turn in self.history:
            messages.extend(turn)
        return messages

    def act(self, calls, response_text=""):
        if self.done:
            raise RuntimeError("Episode already ended")
        self.num_steps += 1
        env_reward = 0.0
        valid = False
        error = None
        try:
            if len(calls) != 1:
                raise ToolCallError("invalid_tool_call: expected exactly one call")
            name, arguments = calls[0]
            command = command_for(name, arguments)
            valid = command in self.info.get("admissible_commands", [])
            self.observation, env_reward, done, self.info = self.env.step(command)
            self.success = bool(self.info.get("success", self.info.get("won", False)))
            self.done = bool(done or self.success)
            feedback = self.observation
        except ToolCallError as exc:
            error = str(exc)
            feedback = error + ". The environment state did not change."
        self.env_reward_sum += float(env_reward)
        self.done = self.done or self.num_steps >= self.max_steps
        # Preserve standard assistant/tool roles, using only model-visible tool names.
        if calls:
            tool_calls = []
            for index, (name, arguments) in enumerate(calls):
                if isinstance(arguments, str):
                    try:
                        arguments = json.loads(arguments)
                    except ValueError:
                        pass
                tool_calls.append({"id": f"call_{self.num_steps}_{index}", "type": "function",
                                   "function": {"name": name, "arguments": arguments}})
            turn = [{"role": "assistant", "content": "", "tool_calls": tool_calls}]
            turn.extend({"role": "tool", "tool_call_id": call["id"], "content": feedback}
                        for call in tool_calls)
        else:
            turn = [{"role": "assistant", "content": response_text},
                    {"role": "user", "content": feedback}]
        self.history.append(turn)
        return {"success": self.success, "score": float(self.done and self.success),
                "num_steps": self.num_steps, "is_action_valid": valid,
                "step_env_reward": float(env_reward), "dense_reward_sum": self.env_reward_sum,
                "tool_error": error or "", "done": self.done, "feedback": feedback}

    def close(self):
        self.env._close_env()

from __future__ import annotations

from typing import Any


def _native_value(value: Any) -> Any:
    if value is None:
        return None
    if hasattr(value, "item"):
        try:
            value = value.item()
        except Exception:
            pass
    if isinstance(value, (str, int, float, bool)):
        return value
    return str(value)


def _native_str(value: Any) -> str | None:
    value = _native_value(value)
    if value is None:
        return ""
    return str(value)


def _native_int(value: Any) -> int | None:
    value = _native_value(value)
    if value is None:
        return 0
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def _native_float(value: Any) -> float | None:
    value = _native_value(value)
    if value is None:
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _maybe_bool(value: Any) -> bool | None:
    if value is None:
        return None
    value = _native_value(value)
    if isinstance(value, bool):
        return value
    return bool(value)


def _default_compute_score(*args, **kwargs):
    from verl.utils.reward_score import default_compute_score

    return default_compute_score(*args, **kwargs)


def compute_score(
    data_source: str,
    solution_str: str,
    ground_truth: Any,
    extra_info: dict | None = None,
    **kwargs,
) -> float | dict[str, Any]:
    if not str(data_source).startswith("alfworld"):
        return _default_compute_score(data_source, solution_str, ground_truth, extra_info, **kwargs)

    extra_info = extra_info or {}
    runtime_info = extra_info.get("reward_extra_info", {}) if isinstance(extra_info, dict) else {}
    if not isinstance(runtime_info, dict):
        runtime_info = {}

    success_flag = None
    if isinstance(ground_truth, dict):
        success_flag = _maybe_bool(ground_truth.get("success"))
    else:
        success_flag = _maybe_bool(ground_truth)

    if success_flag is None:
        success_flag = _maybe_bool(runtime_info.get("success"))
    if success_flag is None:
        success_flag = _maybe_bool(extra_info.get("success")) if isinstance(extra_info, dict) else None

    score = 1.0 if success_flag else 0.0

    result = {
        "score": float(score),
        "step_env_reward": _native_float(runtime_info.get("step_env_reward")) or 0.0,
        "dense_reward_sum": _native_float(runtime_info.get("dense_reward_sum")),
        "success": bool(success_flag),
        "num_steps": _native_int(runtime_info.get("num_steps")),
        "is_action_valid": bool(_maybe_bool(runtime_info.get("is_action_valid"))),
        "task_id": _native_str(runtime_info.get("task_id", extra_info.get("task_id"))),
        "split": _native_str(runtime_info.get("split", extra_info.get("split"))),
        "task_type_raw": _native_str(runtime_info.get("task_type_raw", extra_info.get("task_type_raw"))),
        "task_family": _native_str(runtime_info.get("task_family", extra_info.get("task_family"))),
    }
    return result

from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


def _default_data_root() -> str:
    return os.getenv("ALFWORLD_DATA_ROOT", "data/alfworld")


@dataclass
class AlfworldTextworldEnv:
    data_root: str = field(default_factory=_default_data_root)
    max_episode_steps: int = 50
    _env: Any = field(init=False, default=None)
    _current_game_path: Path | None = field(init=False, default=None)

    def _games_root(self) -> Path:
        return Path(self.data_root).expanduser().resolve() / "games"

    def _resolve_game_path(self, game_relative_path: str) -> Path:
        game_path = self._games_root() / game_relative_path
        if not game_path.exists():
            raise FileNotFoundError(
                f"ALFWorld game file not found: {game_path}. Expected runtime assets under {self._games_root()}."
            )
        return game_path

    def _close_env(self) -> None:
        if self._env is not None and hasattr(self._env, "close"):
            self._env.close()
        self._env = None
        self._current_game_path = None

    def _build_env(self, game_path: Path):
        try:
            import textworld
            import textworld.gym
        except ImportError as e:
            raise ImportError(
                "TextWorld runtime is not installed. Please install ALFWorld/TextWorld dependencies first."
            ) from e

        wrappers: list[Any] = []
        try:
            from alfworld.agents.utils.misc import Demangler

            class AlfredDemangler(textworld.core.Wrapper):
                def __init__(self, *args, shuffle: bool = False, **kwargs):
                    super().__init__(*args, **kwargs)
                    self.shuffle = shuffle

                def load(self, *args, **kwargs):
                    super().load(*args, **kwargs)
                    demangler = Demangler(game_infos=self._entity_infos, shuffle=self.shuffle)
                    for info in self._entity_infos.values():
                        info.name = demangler.demangle_alfred_name(info.id)

            wrappers.append(AlfredDemangler(shuffle=False))
        except Exception:
            # Friendly feedback still exists in game.tw-pddl, so demangling is optional.
            pass

        class AlfredInfos(textworld.core.Wrapper):
            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)
                self._gamefile = None

            def load(self, *args, **kwargs):
                super().load(*args, **kwargs)
                self._gamefile = args[0]

            def reset(self, *args, **kwargs):
                state = super().reset(*args, **kwargs)
                try:
                    state["extra.gamefile"] = self._gamefile
                except Exception:
                    pass
                return state

        wrappers.append(AlfredInfos)

        request_infos = textworld.EnvInfos(
            won=True,
            admissible_commands=True,
            extras=["gamefile"],
        )
        env_id = textworld.gym.register_games(
            [str(game_path)],
            request_infos,
            batch_size=1,
            asynchronous=False,
            max_episode_steps=self.max_episode_steps,
            wrappers=wrappers,
        )
        return textworld.gym.make(env_id)

    def _ensure_env(self, game_path: Path) -> None:
        if self._env is not None and self._current_game_path == game_path:
            return
        self._close_env()
        self._env = self._build_env(game_path)
        self._current_game_path = game_path

    @staticmethod
    def _unwrap_batch_item(value: Any) -> Any:
        if isinstance(value, (list, tuple)) and len(value) == 1:
            return value[0]
        return value

    @staticmethod
    def _batch_info_to_single(info: dict[str, Any] | None) -> dict[str, Any]:
        return {key: AlfworldTextworldEnv._unwrap_batch_item(value) for key, value in dict(info or {}).items()}

    @staticmethod
    def _won_to_success(value: Any) -> bool:
        value = AlfworldTextworldEnv._unwrap_batch_item(value)
        if hasattr(value, "item"):
            try:
                value = value.item()
            except Exception:
                pass
        return bool(float(value))

    def _normalize_reset_output(self, reset_output: Any) -> tuple[Any, dict[str, Any]]:
        if isinstance(reset_output, tuple) and len(reset_output) == 2:
            obs, info = reset_output
            return obs, dict(info or {})
        return reset_output, {}

    def _normalize_step_output(self, step_output: Any) -> tuple[Any, float, bool, dict[str, Any]]:
        if isinstance(step_output, tuple) and len(step_output) == 5:
            obs, reward, terminated, truncated, info = step_output
            reward = self._unwrap_batch_item(reward)
            terminated = self._unwrap_batch_item(terminated)
            truncated = self._unwrap_batch_item(truncated)
            info = self._unwrap_batch_item(info)
            return obs, float(reward), bool(terminated or truncated), dict(info or {})
        if isinstance(step_output, tuple) and len(step_output) == 4:
            obs, reward, done, info = step_output
            reward = self._unwrap_batch_item(reward)
            done = self._unwrap_batch_item(done)
            info = self._unwrap_batch_item(info)
            return obs, float(reward), bool(done), dict(info or {})
        if isinstance(step_output, tuple) and len(step_output) == 3:
            obs, reward, done = step_output
            reward = self._unwrap_batch_item(reward)
            done = self._unwrap_batch_item(done)
            return obs, float(reward), bool(done), {}
        raise RuntimeError(f"Unsupported step() output: {type(step_output)} / {step_output!r}")

    @staticmethod
    def _state_to_observation(state: Any) -> str:
        state = AlfworldTextworldEnv._unwrap_batch_item(state)
        if isinstance(state, dict):
            if "feedback" in state:
                return str(state["feedback"])
            if "observation" in state:
                return str(state["observation"])
        return str(state)

    @staticmethod
    def _state_to_info(state: Any, base_info: dict[str, Any]) -> dict[str, Any]:
        state = AlfworldTextworldEnv._unwrap_batch_item(state)
        info = AlfworldTextworldEnv._batch_info_to_single(base_info)
        if isinstance(state, dict):
            for key in ("won", "admissible_commands", "extra.gamefile"):
                if key in state:
                    info[key] = AlfworldTextworldEnv._unwrap_batch_item(state[key])
        info["success"] = AlfworldTextworldEnv._won_to_success(info.get("won", 0.0))
        return info

    def reset_with_info(self, game_relative_path: str, task_id: str | None = None) -> tuple[str, dict[str, Any]]:
        del task_id  # task_id is carried for logging / debugging; game_relative_path is the runtime selector.
        game_path = self._resolve_game_path(game_relative_path)
        self._ensure_env(game_path)
        raw_state, base_info = self._normalize_reset_output(self._env.reset())
        raw_state = self._unwrap_batch_item(raw_state)
        return self._state_to_observation(raw_state), self._state_to_info(raw_state, base_info)

    def reset(self, game_relative_path: str, task_id: str | None = None) -> str:
        observation, _ = self.reset_with_info(game_relative_path=game_relative_path, task_id=task_id)
        return observation

    def step(self, action_str: str) -> tuple[str, float, bool, dict[str, Any]]:
        if self._env is None:
            raise RuntimeError("Environment not initialized. Call reset() before step().")

        raw_state, reward, done, base_info = self._normalize_step_output(self._env.step([action_str]))
        raw_state = self._unwrap_batch_item(raw_state)
        info = self._state_to_info(raw_state, base_info)
        observation = self._state_to_observation(raw_state)
        return observation, reward, done, info

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from recipes.alfworld.env.alfworld_wrapper import AlfworldTextworldEnv

INVALID_TOOL_CALL_ACTION = "<invalid_tool_call>"


@dataclass
class AlfworldToolExecutor:
    max_episode_steps: int = 50
    _env: AlfworldTextworldEnv = field(init=False)
    _history_actions: list[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        self._env = AlfworldTextworldEnv(max_episode_steps=self.max_episode_steps)

    def reset(self, game_relative_path: str, task_id: str | None = None) -> str:
        self._history_actions.clear()
        return self._env.reset(game_relative_path=game_relative_path, task_id=task_id)

    def reset_with_info(self, game_relative_path: str, task_id: str | None = None) -> tuple[str, dict[str, Any]]:
        self._history_actions.clear()
        return self._env.reset_with_info(game_relative_path=game_relative_path, task_id=task_id)

    def step(self, command: str) -> dict[str, Any]:
        self._history_actions.append(command)
        observation, reward, done, info = self._env.step(command)
        return {
            "observation": str(observation),
            "reward": float(reward),
            "done": bool(done),
            "info": info,
            "history_actions": list(self._history_actions),
        }

