import json, glob, re, collections, sys, os

BASE = sys.argv[1] if len(sys.argv) > 1 else '/workspace/results/baseline63'

pair = collections.Counter()
samples = collections.defaultdict(list)

call_re = re.compile(r'<tool_call>\s*(\{.*?\})\s*</tool_call>', re.S)
resp_re = re.compile(r'<tool_response>\s*(.*?)\s*</tool_response>', re.S)

for f in sorted(glob.glob(os.path.join(BASE, 'validation/*.jsonl'))) + \
         sorted(glob.glob(os.path.join(BASE, 'rollouts/*.jsonl'))):
    for line in open(f):
        d = json.loads(line)
        for st in d.get('steps', []):
            txt = st.get('output', '')
            # Walk the trajectory pairing each tool_call with the next tool_response
            events = []
            for m in call_re.finditer(txt):
                events.append((m.start(), 'call', m.group(1)))
            for m in resp_re.finditer(txt):
                events.append((m.start(), 'resp', m.group(1)))
            events.sort()
            pending = None
            for _, kind, payload in events:
                if kind == 'call':
                    try:
                        name = json.loads(payload).get('name')
                    except Exception:
                        name = '<unparseable>'
                    pending = name
                else:
                    name = pending if pending is not None else '<none>'
                    head = payload.strip().split('\n')[0][:90]
                    if 'unknown_tool' in payload:
                        tag = 'UNKNOWN_TOOL'
                    elif 'invalid_arguments' in payload:
                        tag = 'INVALID_ARGS'
                    elif 'invalid_tool_call' in payload:
                        tag = 'INVALID_CALL'
                    elif payload.strip().startswith('Nothing happens'):
                        tag = 'nothing_happens'
                    else:
                        tag = 'ok'
                    pair[(name, tag)] += 1
                    if len(samples[(name, tag)]) < 2:
                        samples[(name, tag)].append(head)
                    pending = None

names = sorted({n for n, _ in pair})
tags = ['ok', 'nothing_happens', 'UNKNOWN_TOOL', 'INVALID_ARGS', 'INVALID_CALL']
print('%-16s %s' % ('tool', '  '.join('%-15s' % t for t in tags)))
for n in names:
    row = '  '.join('%-15s' % pair.get((n, t), 0) for t in tags)
    print('%-16s %s' % (n, row))

print()
print('--- sample feedback ---')
for (n, t), ex in sorted(samples.items()):
    if t in ('UNKNOWN_TOOL', 'INVALID_ARGS', 'INVALID_CALL') or n in ('clean_object', 'heat_object', 'cool_object'):
        print('%-16s %-15s %s' % (n, t, ex[0] if ex else ''))

import json, glob, os, collections, sys

BASE = sys.argv[1] if len(sys.argv) > 1 else '/workspace/results/baseline63'

FIELDS = ('task_family', 'task_type_raw', 'split')


def get_meta(d):
    for st in d.get('steps', []):
        for f in FIELDS:
            if st.get(f):
                return {k: st.get(k, '') for k in FIELDS}
    return {k: '' for k in FIELDS}


for path in sorted(glob.glob(os.path.join(BASE, 'validation/*.jsonl'))):
    step = os.path.splitext(os.path.basename(path))[0]
    fam = collections.defaultdict(lambda: [0.0, 0])
    n = 0
    for line in open(path):
        d = json.loads(line)
        n += 1
        meta = get_meta(d)
        f = meta.get('task_family') or '?'
        sc = d.get('score')
        ok = 1.0 if (sc is not None and float(sc) >= 1.0) else 0.0
        fam[f][0] += ok
        fam[f][1] += 1
    print('=== validation step %s  (%d episodes) ===' % (step, n))
    tot_s = tot_n = 0
    for f in sorted(fam):
        s, t = fam[f]
        tot_s += s; tot_n += t
        print('   %-28s %6.1f%%  (%3d/%3d)' % (f, 100.0 * s / t, s, t))
    print('   %-28s %6.1f%%  (%3d/%3d)' % ('OVERALL', 100.0 * tot_s / tot_n, tot_s, tot_n))
    print()

