"""Regression tests for the advertised-name -> executor-name contract in tools.py.

The tool schema advertises names the model is allowed to emit; the executor registry
is keyed by internal names. When those two disagree, every affected tool fails with
`unknown_tool` and the corresponding ALFWorld task families become unsolvable while
training still appears to run normally.
"""
import json
import unittest

from alfworld_case.tools import (
    EXECUTOR_NAMES,
    REGISTRY,
    SCHEMA_NAMES,
    ToolCallError,
    command_for,
    tool_schemas,
)


def _sample_args(fields):
    return {
        field: ("sinkbasin 1" if field in ("destination", "source", "receptacle") else "mug 1")
        for field in fields
    }


class AdvertisedNamesExecutable(unittest.TestCase):
    def test_every_advertised_name_resolves(self):
        """No advertised tool may be rejected by the executor."""
        for schema in tool_schemas():
            fn = schema["function"]
            name = fn["name"]
            args = _sample_args(fn["parameters"]["required"])
            try:
                command = command_for(name, args)
            except ToolCallError as exc:  # pragma: no cover - failure path
                self.fail("advertised tool %r is not executable: %s" % (name, exc))
            self.assertIsInstance(command, str)
            self.assertTrue(command.strip())

    def test_advertised_names_cover_registry(self):
        """Every registry entry must be reachable through some advertised name."""
        advertised = {schema["function"]["name"] for schema in tool_schemas()}
        reachable = set(advertised) | set(EXECUTOR_NAMES.values())
        self.assertEqual(set(REGISTRY), reachable - (reachable - set(REGISTRY)) | set(REGISTRY))
        for name in REGISTRY:
            self.assertTrue(
                name in advertised or SCHEMA_NAMES.get(name) in advertised,
                "registry tool %r has no advertised name" % name,
            )

    def test_object_tools_emit_native_commands(self):
        expected = {
            "clean_object": "clean mug 1 with sinkbasin 1",
            "heat_object": "heat mug 1 with sinkbasin 1",
            "cool_object": "cool mug 1 with sinkbasin 1",
        }
        for name, want in expected.items():
            self.assertEqual(command_for(name, {"object": "mug 1", "receptacle": "sinkbasin 1"}), want)

    def test_executor_names_still_accepted(self):
        for name in ("clean", "heat", "cool"):
            self.assertEqual(
                command_for(name, {"object": "mug 1", "receptacle": "sinkbasin 1"}),
                "%s mug 1 with sinkbasin 1" % name,
            )

    def test_schema_names_are_bidirectional(self):
        self.assertEqual({v: k for k, v in SCHEMA_NAMES.items()}, EXECUTOR_NAMES)
        self.assertEqual(len(EXECUTOR_NAMES), len(SCHEMA_NAMES))

    def test_unknown_tools_still_rejected(self):
        for name in ("exit", "clean_objectt", "", "put_object"):
            with self.assertRaises(ToolCallError):
                command_for(name, {})

    def test_schemas_are_independent_copies(self):
        first = tool_schemas()
        first[0]["function"]["name"] = "mutated"
        self.assertNotEqual(tool_schemas()[0]["function"]["name"], "mutated")

    def test_json_string_arguments_accepted(self):
        payload = json.dumps({"object": "mug 1", "receptacle": "sinkbasin 1"})
        self.assertEqual(command_for("clean_object", payload), "clean mug 1 with sinkbasin 1")


if __name__ == "__main__":
    unittest.main(verbosity=2)

